21	/**
22	 * 证物封存交接 API 主流程与失败分支测试。
23	 */
24	@SpringBootTest
25	@AutoConfigureMockMvc
26	class EvidenceApiTest {
27	
28	    private static final String ACTOR_HEADER = "X-Actor-Id";
29	
30	    @Autowired
31	    private MockMvc mockMvc;
32	
33	    @Autowired
34	    private ObjectMapper objectMapper;
35	
36	    private String uniqueKey(String prefix) {
37	        return prefix + "-" + UUID.randomUUID().toString().substring(0, 12);
38	    }
39	
40	    private Map<String, Object> intakeBody(String commandKey, String evidenceKey) {
41	        Map<String, Object> body = new LinkedHashMap<>();
42	        body.put("commandKey", commandKey);
43	        body.put("evidenceKey", evidenceKey);
44	        body.put("caseKey", "CASE-1");
45	        body.put("category", "DOCUMENT");
46	        body.put("sealNo", "SEAL-1");
47	        return body;
48	    }
49	
50	    private MvcResult intake(String actor, String commandKey, String evidenceKey) throws Exception {
51	        return mockMvc.perform(post("/api/evidence")
52	                        .header(ACTOR_HEADER, actor)
53	                        .contentType(MediaType.APPLICATION_JSON)
54	                        .content(objectMapper.writeValueAsString(intakeBody(commandKey, evidenceKey))))
55	                .andReturn();
56	    }
57	
58	    private MvcResult initiate(String actor, String evidenceKey, String commandKey,
59	                               String toCustodian) throws Exception {
60	        Map<String, Object> body = new LinkedHashMap<>();
61	        body.put("commandKey", commandKey);
62	        body.put("toCustodian", toCustodian);
63	        return mockMvc.perform(post("/api/evidence/{key}/transfers", evidenceKey)
64	                        .header(ACTOR_HEADER, actor)
65	                        .contentType(MediaType.APPLICATION_JSON)
66	                        .content(objectMapper.writeValueAsString(body)))
67	                .andReturn();
68	    }
69	
70	    private MvcResult decide(String actor, String evidenceKey, String commandKey,
71	                             String action) throws Exception {
72	        Map<String, Object> body = new LinkedHashMap<>();
73	        body.put("commandKey", commandKey);
74	        return mockMvc.perform(post("/api/evidence/{key}/transfers/{action}", evidenceKey, action)
75	                        .header(ACTOR_HEADER, actor)
76	                        .contentType(MediaType.APPLICATION_JSON)
77	                        .content(objectMapper.writeValueAsString(body)))
78	                .andReturn();
79	    }
80	
81	    private MvcResult inspect(String actor, String evidenceKey, String commandKey,
82	                              boolean passed) throws Exception {
83	        Map<String, Object> body = new LinkedHashMap<>();
84	        body.put("commandKey", commandKey);
85	        body.put("passed", passed);
86	        body.put("note", "routine");
87	        return mockMvc.perform(post("/api/evidence/{key}/seal-inspections", evidenceKey)
88	                        .header(ACTOR_HEADER, actor)
89	                        .contentType(MediaType.APPLICATION_JSON)
90	                        .content(objectMapper.writeValueAsString(body)))
91	                .andReturn();
92	    }
93	
94	    private JsonNode chain(String evidenceKey) throws Exception {
95	        MvcResult result = mockMvc.perform(get("/api/evidence/{key}/custody-chain", evidenceKey))
96	                .andReturn();
97	        assertThat(result.getResponse().getStatus()).isEqualTo(200);
98	        return objectMapper.readTree(result.getResponse().getContentAsString());
99	    }
100	
101	    @Test
102	    void intakeCreatesSealedEvidenceWithActorAsCustodian() throws Exception {
103	        String evidenceKey = uniqueKey("EV");
104	        MvcResult result = intake("alice", uniqueKey("CMD"), evidenceKey);
105	
106	        assertThat(result.getResponse().getStatus()).isEqualTo(201);
107	        JsonNode body = objectMapper.readTree(result.getResponse().getContentAsString());
108	        assertThat(body.get("evidenceKey").asText()).isEqualTo(evidenceKey);
109	        assertThat(body.get("custodianId").asText()).isEqualTo("alice");
110	        assertThat(body.get("status").asText()).isEqualTo("SEALED");
111	        assertThat(body.get("caseKey").asText()).isEqualTo("CASE-1");
112	    }
113	
114	    @Test
115	    void intakeDuplicateEvidenceKeyReturns409() throws Exception {
116	        String evidenceKey = uniqueKey("EV");
117	        assertThat(intake("alice", uniqueKey("CMD"), evidenceKey).getResponse().getStatus())
118	                .isEqualTo(201);
119	        assertThat(intake("alice", uniqueKey("CMD"), evidenceKey).getResponse().getStatus())
120	                .isEqualTo(409);
121	    }
122	
123	    @Test
124	    void intakeIdempotentReplayReturnsFirstResult() throws Exception {
125	        String evidenceKey = uniqueKey("EV");
126	        String commandKey = uniqueKey("CMD");
127	        MvcResult first = intake("alice", commandKey, evidenceKey);
128	        MvcResult replay = intake("alice", commandKey, evidenceKey);
129	
130	        assertThat(first.getResponse().getStatus()).isEqualTo(201);
131	        assertThat(replay.getResponse().getStatus()).isEqualTo(201);
132	        assertThat(replay.getResponse().getContentAsString())
