138	        String commandKey = uniqueKey("CMD");
139	        assertThat(intake("alice", commandKey, uniqueKey("EV")).getResponse().getStatus())
140	                .isEqualTo(201);
141	        assertThat(intake("alice", commandKey, uniqueKey("EV")).getResponse().getStatus())
142	                .isEqualTo(409);
143	    }
