145	    @Test
146	    void intakeWithMissingFieldsReturns400() throws Exception {
147	        Map<String, Object> body = new LinkedHashMap<>();
148	        body.put("commandKey", uniqueKey("CMD"));
149	        MvcResult result = mockMvc.perform(post("/api/evidence")
