app_path=$0
while [ -h "$app_path" ]; do
    ls=$(ls -ld "$app_path")
    link=${ls#*' -> '}
    case $link in
      /*) app_path=$link ;;
      *)  app_path=$(dirname "$app_path")/$link ;;
    esac
done
app_dir=${app_path%"${app_path##*/}"}
APP_HOME=$(cd "${app_dir:-.}" >/dev/null && pwd) || exit

