            assertThat(evidence.status()).isEqualTo(EvidenceStatus.DESTROYED);
            assertThat(statuses).containsExactlyInAnyOrder(200, 409);
        } else {
            // 借出先提交：执行事务内重查发现证物已变 BORROWED，整单 409 回滚，
